void fm1_fault_c(uint32_t *f)
{
    static volatile uint32_t in_fault;
    uint32_t i, count = fm1_crash.magic == FM1_CRASH_MAGIC ? fm1_crash.count : 0;
    uint32_t early = fm1_crash.magic == FM1_CRASH_MAGIC ? fm1_crash.early : 0;
#if FM1_CPU1_USED
    if (f[24] >= (uint32_t)(uintptr_t)_c1_ustack && f[24] <= (uint32_t)(uintptr_t)_c1_sstack_top) {
        /* the second core faulted (after Jangada, as Felucca 1.6.1): this runs on it. Its record only, no screen and no
         * reset from here (a reset from core 1 would hold core 1 first, itself: a frozen FM-1). It stops; core 0's
         * next wait times out (fm1_cpu1_wait), holds it, and the FM-1 goes on with one core */
        fm1_crash.magic = FM1_CRASH_MAGIC;
        fm1_crash.count = count + 1u;
        fm1_crash.core = 1;
        fm1_crash.vec = (f[19] - (uint32_t)(uintptr_t)fm1_fatal_stubs) / 6u - 1u;
        fm1_crash.pc = f[16];
        fm1_crash.rets = f[25];
        fm1_crash.sp = f[24];
        fm1_crash.psr = f[20];
        fm1_crash.icfg = f[21];
        fm1_crash.uptime_ms = *(volatile uint32_t *)0x10804u / 24000u;
        __asm__ volatile("csync" ::: "memory");
        for (;;)
            ;
    }
#endif
    fm1_irq_off();
    if (in_fault++) {                         /* fault while reporting: reset at once */
        FM1_RESET_PREP();
        *(volatile uint32_t *)0x10000u |= 1u << 4;
    }
    fm1_crash.magic = FM1_CRASH_MAGIC;
    fm1_crash.count = count + 1u;
    fm1_crash.vec = (f[19] - (uint32_t)(uintptr_t)fm1_fatal_stubs) / 6u - 1u;
    fm1_crash.pc = f[16];
    fm1_crash.rets = f[25];
    fm1_crash.emu = FM1_EMU_MSG;
    fm1_crash.dbg = FM1_DBG_MSG;
    fm1_crash.sp = f[24];
    fm1_crash.psr = f[20];
    fm1_crash.icfg = f[21];
    fm1_crash.uptime_ms = *(volatile uint32_t *)0x10804u / 24000u;   /* TIMER4 since boot */
    for (i = 0; i < 4u; i++)
        fm1_crash.etm[i] = FM1_ETM_PC(i);
    fm1_crash.early = fm1_crash.uptime_ms < 3000u ? early + 1u : 0u;
#if FM1_CPU1_USED
    fm1_crash.core = 0;
#endif
    fm1_fault(&fm1_crash);
    for (;;)
        ;
}

static void seq_stop(void)
{
    uint32_t i;
#if BOARD_SMK37
    if (song.playing && !song.g[G_CLOCK])
        smk_uart_tx_put(0xFCu);                    /* (the TRS jack: Stop) */
#endif
    song.playing = 0;
    thr_out = 0;                                   /* (Skiff) the throws back at once (throw.c) */
    cin_left = 0;                                  /* (a count-in: cancelled, nothing recorded) */
    cin_flush = 0;
    memset(cin_n, 0, sizeof cin_n);
    if (song.g[G_CLOCK])                           /* external clock: the arp stops with the transport, */
        for (i = 0; i < NPART; i++)                /* its sounding note too (HOLD keeps the latched chord) */
            if (trk[i].arp_note)
                arp_off(&trk[i]);
    for (i = 0; i < NTRK; i++) {
        seq_release(&trk[i]);
        trk[i].rh_n = 0;                           /* a recorded note held over the stop: as far as it got */
        trk[i].rat_left = 0;
        trk[i].nud = 0;                            /* (Skiff) no NUDGE pending */
    }
    memset(fol_src, 0, sizeof fol_src);            /* ((2.1) no chords: the followers as written until theirs play) */
    motion_end();
}

/* how far track t moves for the chord s (its NOTE d semitones above t's ROOT): KEY semitones, SCALE scale steps (to
 * the scale note at or below it), the nearest way */
static int32_t fol_shift(const track_t *t, const fol_src_t *s)
{
    int32_t d = t->p[P_FNOTE] == FN_LOW ? s->lo : t->p[P_FNOTE] == FN_HIGH ? s->hi : t->p[P_FNOTE] == FN_LAST ? s->last : s->root;
    int32_t below, all;
    d = (d - t->p[P_ROOT] + 120) % 12;
    if (t->p[P_FMODE] != FM_SCALE)
        return d > 6 ? d - 12 : d;
    fol_count(scale_mask(t), d, &below, &all);
    return below - 1 > all / 2 ? below - 1 - all : below - 1;
}

static uint32_t key_place(uint32_t k)
