static inline const smp_zone_t *smp_zone(uint32_t zi)
{
    return zi < 0x8000u ? &SMP_ZONES[zi] : &usr_zone[(zi >> 5) & 3u][zi & 31u];
}

/* a line `thick` px tall (the scope's trace: 2). (Skiff N4) THEME NEON: a curve (2 px and more) glows, a ring 1 px out
 * of it on the background only (a polyline's next segment never covers the last) */
static void cv_line_t(int32_t x0, int32_t y0, int32_t x1, int32_t y1, uint16_t c, int32_t thick)
{
    int32_t t, d;
    if (ux.neon && thick >= 2) {
        uint16_t g = ux_mix(c, cv_bg, 62);
        cv_glow = 1;
        for (t = -1; t <= thick; t++)
            for (d = -1; d <= 1; d++)
                cv_line(x0 + d, y0 + t, x1 + d, y1 + t, g);
        cv_glow = 0;
    }
    for (t = 0; t < thick; t++)
        cv_line(x0, y0 + t, x1, y1 + t, c);
}

/* a laser frame (the cursor): its glow 1 px out, the frame in the accent */
static void ne_laser(int32_t x, int32_t y, int32_t w, int32_t h, uint16_t under)
{
    cv_frame(x - 1, y - 1, w + 2, h + 2, ux_mix(T_ACCENT, under, 60));
    cv_frame(x, y, w, h, T_ACCENT);
}

#define HEAD_BAT_X 214                                 /* the battery's cell */
