/* the width cv_free_hint(x, .., s, .., maxw) draws (its word, keycap and the ellipsised rest) */
static int32_t head_hint_w(const char *s, int32_t maxw)
{
    char b[64], p[64];
    kc_words(p, sizeof p, s, 1);                       /* (Skiff) the words (gfx.c kc_words) */
